CREATE   PROC dbo.TESTSIMILITUDINE_CaseN_MegaMixt
    @An INT,
    @Prag DECIMAL(18,2),
    @Gen CHAR(1),
    @IDComanda INT
AS
BEGIN
    SET NOCOUNT ON;

    CREATE TABLE #Vanzari (ID INT, Suma DECIMAL(18,2), An INT, Gen CHAR(1), Activ BIT);
    CREATE TABLE #VanzariFiltrate (ID INT, Suma DECIMAL(18,2), DataCopiere DATETIME);
    CREATE TABLE #Comenzi (ID INT, Stare VARCHAR(20), Incercari INT);

    INSERT INTO #Vanzari (ID, Suma, An, Gen, Activ) VALUES
    (1, 500.00, 2024, 'M', 1),
    (2, 700.00, 2024, 'F', 1),
    (3, 900.00, 2024, 'M', 0);

    INSERT INTO #VanzariFiltrate (ID, Suma, DataCopiere)
    SELECT ID, Suma, GETDATE()
    FROM #Vanzari
    WHERE An = @An AND Suma > @Prag AND Activ = 1;

    WITH VanzariCTE AS (
        SELECT
            ID,
            Suma
        FROM #VanzariFiltrate
    ),
    TotalCTE AS (
        SELECT SUM(Suma) AS Total, COUNT(*) AS Nr FROM VanzariCTE
    )
    SELECT
        v.ID,
        v.Suma,
        CASE

            WHEN @Gen = 'F' THEN 'Feminin'

            WHEN @Gen = 'M' THEN 'Masculin'

            ELSE 'Incomplet'

        END AS GenDescriere,
        t.Total,
        t.Nr
    FROM VanzariCTE v
    CROSS JOIN TotalCTE t
    WHERE EXISTS (
        SELECT 1
        FROM #Vanzari vv
        WHERE vv.ID = v.ID
          AND vv.Gen = @Gen
          AND vv.Activ = 1
    );

    DECLARE @Mesaj NVARCHAR(200);
    SET @Mesaj = 'Raport: SELECT executat cu succes pt ''client'' vip
linia a doua cu text simulat si modificat';

    DECLARE @ID INT, @Suma DECIMAL(18,2);
    DECLARE CursorVanzari CURSOR GLOBAL FOR
        SELECT ID, Suma
        FROM #VanzariFiltrate
        WHERE Suma > @Prag;

    OPEN CursorVanzari;
    FETCH NEXT FROM CursorVanzari INTO @ID, @Suma;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        PRINT @Mesaj;
        FETCH NEXT FROM CursorVanzari INTO @ID, @Suma;
    END;
    CLOSE CursorVanzari;
    DEALLOCATE CursorVanzari;

    IF @Prag > 0
    BEGIN
        PRINT 'Prag pozitiv confirmat';
    END

    INSERT INTO #Comenzi (ID, Stare, Incercari) VALUES (@IDComanda, 'NOU', 0);

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE #Comenzi SET Stare = 'PROCESARE' WHERE ID = @IDComanda;

        BEGIN TRY
            IF @IDComanda <= 0
                THROW 51000, 'ID invalid sau lipsa', 1;

            UPDATE #Comenzi SET Stare = 'OK', Incercari = Incercari + 1 WHERE ID = @IDComanda;
        END TRY
        BEGIN CATCH
            UPDATE #Comenzi SET Stare = 'RETRY', Incercari = Incercari + 1 WHERE ID = @IDComanda;
        END CATCH;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
    END CATCH;

    DROP TABLE #Vanzari;
    DROP TABLE #VanzariFiltrate;
    DROP TABLE #Comenzi;
END;

CREATE   PROC dbo.TESTSIMILITUDINE_ProcesarePlati
    @IDBatch INT,
    @Utilizator VARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    
    -- [SIMULARE TABELE FIZICE]
    CREATE TABLE #PlatiTemporare (
        ID INT,
        IDBatch INT,
        Suma DECIMAL(18,2),
        ContDestinatar VARCHAR(34),
        Stare VARCHAR(20)
    );

    CREATE TABLE #ConturiBancare (
        IDUtilizator VARCHAR(50),
        ContIBAN VARCHAR(34),
        Sold DECIMAL(18,2)
    );

    CREATE TABLE #LogTranzactii (
        IDPlata INT,
        DataInregistrare DATETIME,
        Status VARCHAR(20),
        Operator VARCHAR(100)
    );

    CREATE TABLE #LogErori (
        IDPlata INT,
        MesajEroare NVARCHAR(4000),
        DataEroare DATETIME,
        Severitate INT
    );

    -- [POPULARE DATE TEST]
    INSERT INTO #ConturiBancare (IDUtilizator, ContIBAN, Sold) VALUES
    (@Utilizator, 'RO39SURSA1234567890', 1500.00),
    ('Altu', 'RO89TINTA9876543210', 0.00);

    INSERT INTO #PlatiTemporare (ID, IDBatch, Suma, ContDestinatar, Stare) VALUES
    (1, @IDBatch, 300.00, 'RO89TINTA9876543210', 'PENDING'),
    (2, @IDBatch, 2000.00, 'RO89TINTA9876543210', 'PENDING'); -- Va fi marcat ca INSOLVENT direct la verificarea de sold în varianta Țintă

    -- [LOGICA PROCEDURII]
    DECLARE @IDPlata INT;
    DECLARE @Suma DECIMAL(18,2);
    DECLARE @ContDestinatar VARCHAR(34);
    DECLARE @SoldCurent DECIMAL(18,2);
    
    DECLARE CursorPlati CURSOR GLOBAL FOR 
        SELECT ID, Suma, ContDestinatar
        FROM #PlatiTemporare
        WHERE IDBatch = @IDBatch AND Stare = 'PENDING';
        
    OPEN CursorPlati;
    FETCH NEXT FROM CursorPlati INTO @IDPlata, @Suma, @ContDestinatar;
    
    WHILE @@FETCH_STATUS = 0
    BEGIN
        -- Validare suplimentară înainte de tranzacție
        SELECT @SoldCurent = Sold FROM #ConturiBancare WHERE IDUtilizator = @Utilizator;
        
        IF @SoldCurent < @Suma
        BEGIN
            UPDATE #PlatiTemporare SET Stare = 'INSOLVENT' WHERE ID = @IDPlata;
            INSERT INTO #LogErori (IDPlata, MesajEroare, DataEroare, Severitate)
            VALUES (@IDPlata, 'Fonduri insuficiente direct la verificare pre-tranzactie.', GETDATE(), 16);
        END
        ELSE
        BEGIN
            BEGIN TRY
                BEGIN TRANSACTION;
                    
                    UPDATE #ConturiBancare 
                    SET Sold = Sold - @Suma 
                    WHERE IDUtilizator = @Utilizator;
                    
                    UPDATE #ConturiBancare 
                    SET Sold = Sold + @Suma 
                    WHERE ContIBAN = @ContDestinatar;
                    
                    INSERT INTO #LogTranzactii (IDPlata, DataInregistrare, Status, Operator)
                    VALUES (@IDPlata, GETDATE(), 'SUCCES', SYSTEM_USER);
                    
                    UPDATE #PlatiTemporare 
                    SET Stare = 'PROCESSED' 
                    WHERE ID = @IDPlata;
                    
                COMMIT TRANSACTION;
            END TRY
            BEGIN CATCH
                IF @@TRANCOUNT > 0
                    ROLLBACK TRANSACTION;
                    
                INSERT INTO #LogErori (IDPlata, MesajEroare, DataEroare, Severitate)
                VALUES (@IDPlata, ERROR_MESSAGE(), GETDATE(), ERROR_SEVERITY());
                
                UPDATE #PlatiTemporare 
                SET Stare = 'ERROR_CATCH' 
                WHERE ID = @IDPlata;
            END CATCH;
        END;
        
        FETCH NEXT FROM CursorPlati INTO @IDPlata, @Suma, @ContDestinatar;
    END;
    
    CLOSE CursorPlati;
    DEALLOCATE CursorPlati;

    -- Afișare rezultate finale de test înainte de drop-ul tabelelor
    SELECT 'Plati' AS Tabel, * FROM #PlatiTemporare;
    SELECT 'Conturi' AS Tabel, * FROM #ConturiBancare;
    SELECT 'LogTranzactii' AS Tabel, * FROM #LogTranzactii;
    SELECT 'LogErori' AS Tabel, * FROM #LogErori;

    DROP TABLE #PlatiTemporare;
    DROP TABLE #ConturiBancare;
    DROP TABLE #LogTranzactii;
    DROP TABLE #LogErori;
END;

CREATE   PROC dbo.TESTSIMILITUDINE_RapoarteDinamice
    @NumeTabela VARCHAR(100),
    @CampFiltru VARCHAR(50),
    @ValoareFiltru NVARCHAR(250),
    @ConfigurariJSON NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Creăm fizic tabela pe care o va apela scriptul dinamic dacă aceasta este cea cerută în parametri
    IF @NumeTabela = 'DateVanzariSimulate' AND OBJECT_ID('tempdb..##DateVanzariSimulate') IS NULL
    BEGIN
        CREATE TABLE ##DateVanzariSimulate (
            ID INT,
            NumeProdus NVARCHAR(100),
            Categorie NVARCHAR(50),
            IsActive BIT
        );
        INSERT INTO ##DateVanzariSimulate VALUES 
        (1, 'Laptop', 'IT', 1),
        (2, 'Telefon', 'IT', 0),
        (3, 'Scaun', 'Furniture', 1);
    END

    -- Schimbat din tabel temporar (#) în variabilă tabelă (@)
    DECLARE @CheiRaportare TABLE (
        Cheie NVARCHAR(100),
        TipDate NVARCHAR(50)
    );
    
    INSERT INTO @CheiRaportare (Cheie, TipDate)
    SELECT [key], [type] 
    FROM OPENJSON(@ConfigurariJSON);
    
    DECLARE @DynamicSQL NVARCHAR(MAX);
    
    DECLARE @TabelaDeRulare NVARCHAR(250) = @NumeTabela;
    IF @NumeTabela = 'DateVanzariSimulate' 
        SET @TabelaDeRulare = '##DateVanzariSimulate';

    -- Dynamic SQL modificat pentru a accepta și un filtru activ implicit
    SET @DynamicSQL = N'SELECT *, GETDATE() AS DataRulare FROM ' + QUOTENAME(@TabelaDeRulare) + 
                      N' WHERE ' + QUOTENAME(@CampFiltru) + N' = @Valoare AND IsActive = 1';
                      
    EXEC sp_executesql 
        @DynamicSQL, 
        N'@Valoare NVARCHAR(250)', 
        @Valoare = @ValoareFiltru;

    IF OBJECT_ID('tempdb..##DateVanzariSimulate') IS NOT NULL
        DROP TABLE ##DateVanzariSimulate;
END;
